   168	        try (Connection connection = dataSource.getConnection();
   169	                PreparedStatement select = connection.prepareStatement(
   170	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
   171	                ResultSet rows = select.executeQuery()) {
   172	            List<Message> messages = new ArrayList<>();
   173	            while (rows.next()) {
